 internal static string CompactHolidayBasis(Result value,bool guard,bool weekly=false){if(guard)return "당직전담실무원 · 주휴수당 미산정";var paid=value.Weeks.FirstOrDefault(w=>w.Holiday>0)??value.Weeks.FirstOrDefault(w=>w.ReferenceDays>0);decimal hours=paid==null?value.ReferenceHours:paid.ReferenceHours,unit=paid==null?value.HolidayUnit:paid.HolidayUnit;int days=paid==null?value.ReferenceDays:paid.ReferenceDays;if(days<=0)return "통상근로자 근무일을 확인하세요.";bool capped=hours/days>unit;return (weekly?"주 약정 ":"기간 약정 ")+hours.ToString("0.####")+(weekly?"시간 ÷ 통상 주 ":"시간 ÷ 통상근무 ")+days+"일 "+(capped?"→ ":"= ")+unit.ToString("0.####")+"시간"+(capped?" (1일 상한)":"");}
 internal static string ContractHolidayCaption(Record record,Result value,bool guard){
  string basis=CompactHolidayBasis(value,guard,record.ScheduleMode==0);if(guard||record.ScheduleMode!=0)return basis;
  decimal hours=WorkPlan.Contract(record).Count*record.Hours;int days=WorkPlan.Comparison(record).Count;
  var paid=value.Weeks.FirstOrDefault(w=>w.Holiday>0)??value.Weeks.FirstOrDefault(w=>w.ReferenceDays>0);decimal unit=paid==null?value.HolidayUnit:paid.HolidayUnit;
  if(days>0&&hours/days==unit)return "계약기간 "+hours.ToString("0.####")+"시간 ÷ "+days+"일 = "+unit.ToString("0.####")+"시간";
  return "계약기간 약정 "+hours.ToString("0.####")+"시간 · 통상근무 "+days+"일\n"+basis;
 }
